require_once __DIR__.'/lib/staging-common.php';$root=Ch247Staging::root($argv[1]??'');$output=$argv[2]??null;require$root.'/init.php';use WHMCS\Database\Capsule;$environment=Ch247Staging::verifyEnvironment($root);
$definitions=array('tblinvoices'=>array('id','userid','status','subtotal','tax','tax2','total','credit','balance','date','duedate','datepaid'),'tblinvoiceitems'=>array('id','invoiceid','userid','type','relid','amount','taxed'),'tblaccounts'=>array('id','userid','invoiceid','amountin','fees','amountout','date','transid'),'tblclients'=>array('id','status','currency','credit'),'tblpricing'=>array('id','type','currency','relid','msetupfee','qsetupfee','ssetupfee','asetupfee','bsetupfee','tsetupfee','monthly','quarterly','semiannually','annually','biennially','triennially'),'tblcurrencies'=>array('id','code','rate','default'),'tblhosting'=>array('id','userid','packageid','domainstatus','billingcycle','amount','nextduedate','termination_date'),'tbldomains'=>array('id','userid','status','registrationperiod','recurringamount','nextduedate','expirydate'));
